const d = $input.first().json; const r = d.indicadores.resumo; const b = d.linhaDeBase ?? {};
const f = (v, s = '') => v === null || v === undefined ? 'sem dados' : Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + s;
const comp = (atual, base, s) => base === undefined ? '' : ` (linha de base do diagnóstico: ${f(base, s)})`;
const linhas = [
  `Relatório mensal de pricing: ${d.organizacao}, ${d.mes}`, '',
  `Cotações emitidas: ${f(r.emitidas)}; fechadas: ${f(r.aceitas)}`,
  `Conversão: ${f(r.conversaoPct, '%')}${comp(r.conversaoPct, b.conversaoPct, '%')}`,
  `Margem das fechadas: ${f(r.margemPct, '%')}${comp(r.margemPct, b.margemPct, '%')}`,
  `Desconto médio: ${f(r.descontoMedioPct, '%')}${comp(r.descontoMedioPct, b.descontoMedioPct, '%')}`,
  `Cotações com exceção: ${f(r.excecaoPct, '%')}`,
  `Tempo médio de aprovação: ${f(d.indicadores.aprovacoes.horasAteDecisao, ' h')}`, '',
  'Margem por canal:', ...d.indicadores.porCanal.map((c) => `  ${c.canal}: ${f(c.margemPct, '%')} em ${c.aceitas} fechadas`), '',
  'Motivos de perda:', ...d.indicadores.motivosPerda.map((m) => `  ${m.motivo}: ${m.quantidade}`),
  ...(d.anomalias ? ['', 'Padrões a conferir (análise assistida por IA, sem valor de decisão):', d.anomalias] : []),
];
return [{ json: { para: d.para.join(','), assunto: `Pricing: relatório de ${d.mes}`, texto: linhas.join('\n') } }];
